function parseMoneyInput(value, options) {
  return ErpMoney.parseInput(value, options);
}

function moneyToCents(value, options) {
  return ErpMoney.toCents(value, options);
}

function centsToMoney(cents) {
  return ErpMoney.fromCents(cents);
}

function normalizeMoney(value, options) {
  return ErpMoney.normalize(value, options);
}

function moneyEquals(left, right) {
  return ErpMoney.equals(left, right);
}

function formatMoneyInput(value) {
  return ErpMoney.format(value, { withSymbol: false });
}

// Compatibilidad: el parser histórico devuelve cero ante vacío o error.
function parseMoney(value) {
  const result = parseMoneyInput(value, { allowNegative: true });
  return result.ok && !result.empty ? result.amount : 0;
}

function parseQuantity(value) {
  const text = String(value || "")
    .replace(/\s/g, "")
    .trim();

  if (!text) return 0;

  const normalized = text.includes(",") && !text.includes(".")
    ? text.replace(",", ".")
    : text.replace(/,/g, "");
  const number = Number(normalized);
  return Number.isFinite(number) ? number : 0;
}

function parseRate(value) {
  const text = String(value || "").replace("%", "").trim();
  if (!text) return 0;
  const number = parseQuantity(text);
  if (!Number.isFinite(number)) return 0;
  return number > 1 ? number / 100 : number;
}

// Render principal: calcula una vez el reporte mensual y reutiliza ese resultado.

function sum(rows, key) {
  return rows.reduce((total, row) => total + (Number(row[key]) || 0), 0);
}

function formatMoney(value) {
  return ErpMoney.format(parseMoney(value));
}

function formatBankMoney(value) {
  return ErpMoney.format(parseMoney(value));
}

function formatCompactMoney(value) {
  return formatMoney(value);
}

function moneyInputAllowsNegative(input) {
  const setting = input.getAttribute("data-money-allow-negative");
  return setting === "" || setting === "true" || setting === "1";
}

function moneyInputErrorMessage(error) {
  if (error === "EMPTY_NOT_ALLOWED") {
    return "Ingresá un importe.";
  }
  if (error === "TOO_MANY_DECIMALS") {
    return "Ingresá como máximo dos decimales.";
  }
  if (error === "NEGATIVE_NOT_ALLOWED") {
    return "El importe no puede ser negativo.";
  }
  if (error === "UNSAFE_RANGE") {
    return "El importe supera el rango admitido.";
  }
  return "Ingresá un importe válido.";
}

if (typeof document !== "undefined") {
  document.addEventListener("input", (event) => {
    const input = event.target.closest?.("[data-money-input]");
    if (input) input.setCustomValidity("");
  });

  document.addEventListener("blur", (event) => {
    const input = event.target.closest?.("[data-money-input]");
    if (!input) return;

    const result = parseMoneyInput(input.value, {
      allowNegative: moneyInputAllowsNegative(input)
    });
    if (result.empty) {
      input.setCustomValidity("");
      return;
    }
    if (!result.ok) {
      input.setCustomValidity(moneyInputErrorMessage(result.error));
      return;
    }

    input.setCustomValidity("");
    input.value = formatMoneyInput(result.amount);
  }, true);
}

function formatPercentOfSales(value, base) {
  if (!base) return "-";
  return new Intl.NumberFormat("es-AR", {
    style: "percent",
    minimumFractionDigits: 1,
    maximumFractionDigits: 1
  }).format(value / base);
}

function formatPercentValue(value) {
  return `${value > 0 ? "+" : ""}${new Intl.NumberFormat("es-AR", {
    minimumFractionDigits: 1,
    maximumFractionDigits: 1
  }).format(value)}%`;
}

function formatRoundedPercentValue(value) {
  return `${value > 0 ? "+" : ""}${Math.round(value)}%`;
}

function percentValue(value, base) {
  return base ? value / base : 0;
}

function formatNumber(value) {
  return new Intl.NumberFormat("es-AR", {
    maximumFractionDigits: 2
  }).format(value || 0);
}

function formatRoundedNumber(value) {
  return String(roundedNumberValue(value));
}

function roundedNumberValue(value) {
  return Math.round(value || 0);
}

function formatDate(value) {
  if (!value) return "";
  const [year, month, day] = value.split("-");
  return `${day}/${month}/${year}`;
}

function formatMonthYear(value) {
  if (!value) return "";
  const [year, month] = value.split("-");
  return `${MONTHS[Number(month) - 1]} ${year}`;
}

// Escape defensivo para datos importados antes de insertarlos como HTML.
function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function emptyRow(colspan, message) {
  return `<tr><td class="empty" colspan="${colspan}">${message}</td></tr>`;
}

function labelForKind(kind) {
  return {
    expenses: "Egresos",
    sales: "Ventas",
    orderDetails: "Detalle pedidos",
    inventory: "Inventario",
    inventoryDetails: "Detalle inventario",
    payroll: "Sueldos",
    cash: "Caja",
    issuedChecks: "Cheques entregados",
    receivedChecks: "Cheques recibidos",
    creditors: "Acreedores",
    purchases: "Compras",
    purchaseDetails: "Detalle compras",
    providers: "Proveedores",
    recipes: "Recetas",
    itemInfo: "Items",
    supplyInfo: "Insumos"
  }[kind] || kind;
}
